# ----- New spec types for the release -----
class Auto(object):
    """Automatically build a spec based on the target's structure."""
    def __init__(self, subspec=T, *args, **kwargs):
        self.subspec = subspec
    def glomit(self, target, scope):
        return scope[glom](target, self.subspec, scope)
    def __repr__(self):
        return 'Auto(%r)' % self.subspec

class Fill(object):
    """Fill missing values with defaults."""
    def __init__(self, func):
        self.func = func
    def glomit(self, target, scope):
        if target is _MISSING:
            return self.func()
        return target
    def __repr__(self):
        return 'Fill(%r)' % self.func

class Invoke(object):
    """Invoke a callable on the target."""
    def __init__(self, func=None, args=None, kwargs=None):
        self.func = func
        self.args = args or []
        self.kwargs = kwargs or {}
    def glomit(self, target, scope):
        func = self.func
        if func is None:
            func = target
            return func()
        # evaluate args and kwargs
        args = [scope[glom](target, a, scope) if isinstance(a, (Spec, TType)) else a for a in self.args]
        kwargs = {k: scope[glom](target, v, scope) if isinstance(v, (Spec, TType)) else v for k, v in self.kwargs.items()}
        return func(*args, **kwargs)
    def __repr__(self):
        return 'Invoke(%r)' % self.func

class Iter(object):
    """Iterate over target and apply a subspec to each element."""
    def __init__(self, subspec=T):
        self.subspec = subspec
    def glomit(self, target, scope):
        return scope[glom](target, [self.subspec], scope)
    def __repr__(self):
        return 'Iter(%r)' % self.subspec

class Let(object):
    """Bind variables for use in subspecs."""
    def __init__(self, **bindings):
        self.bindings = bindings
    def glomit(self, target, scope):
        new_scope = scope.new_child({k: scope[glom](target, v, scope) if callable(v) else v for k, v in self.bindings.items()})
        return scope[glom](target, self.subspec, new_scope) if hasattr(self, 'subspec') else target
    def __repr__(self):
        return 'Let(%s)' % ', '.join('%s=%r' % (k, v) for k, v in self.bindings.items())

